def dehydrate_time(value):
    """Dehydrator for `time` values.

    :param value:
    :type value: Time
    :return: string representation of the time in ISO 8601 format, or None if value is None
    """
    if value is None:
        return None
    try:
        # Ensure the object behaves like a time
        if not hasattr(value, "hour") or not hasattr(value, "minute") or not hasattr(value, "second"):
            raise TypeError("Expected a time-like object")
        # Prefer the built‑in isoformat if available
        if hasattr(value, "isoformat"):
            return value.isoformat()
        # Fallback manual formatting
        hour = getattr(value, "hour")
        minute = getattr(value, "minute")
        second = getattr(value, "second")
        microsecond = getattr(value, "microsecond", 0)
        if microsecond:
            return f"{hour:02d}:{minute:02d}:{second:02d}.{microsecond:06d}"
        return f"{hour:02d}:{minute:02d}:{second:02d}"
    except Exception as exc:
        raise ValueError(f"Could not dehydrate time value: {exc}") from exc

def dehydrate_point(value):
    """ Dehydrator for Point data.

    :param value:
    :type value: Point
    :return:
    """
    if value is None:
        return None
    try:
        lat = getattr(value, "lat")
        lon = getattr(value, "lon")
        time = getattr(value, "time")
    except AttributeError as exc:
        raise ValueError("value must have 'lat', 'lon', and 'time' attributes") from exc

    # Convert time to ISO format if it is a datetime-like object
    if hasattr(time, "isoformat"):
        time_str = time.isoformat()
    else:
        time_str = str(time)

    return {"lat": lat, "lon": lon, "time": time_str}

def keys(self):
    """Return the keys of the record.

    :return: list of key names
    """
    try:
        # Attempt to retrieve the underlying record data
        record = getattr(self, "_record", None)
        if record is None:
            record = getattr(self, "data", None)

        # If the record is a dictionary, return its keys
        if isinstance(record, dict):
            return list(record.keys())

        # If the record is an object with a __dict__, return its attribute names
        if hasattr(record, "__dict__"):
            return list(record.__dict__.keys())

        # Fallback: return an empty list if the record type is unsupported
        return []
    except Exception:
        # In case of any unexpected error, return an empty list
        return []

def index(self, key):
    """ Return the index of the given item.

    :param key: a key
    :return: index
    :rtype: int
    """
    try:
        # If the internal index is a dictionary mapping keys to positions
        if isinstance(self._index, dict):
            return self._index[key]
        # Otherwise assume it is a list or sequence
        return self._index.index(key)
    except (KeyError, ValueError, AttributeError):
        raise KeyError(f"Key not found: {key}") from None

def data(self, *keys):
    """
    Return the keys and values of this record as a dictionary,
    optionally including only certain values by index or key. Keys
    provided in the items that are not in the record will be
    inserted with a value of :const:`None`; indexes provided
    that are out of bounds will trigger an :exc:`IndexError`.

    :param keys: indexes or keys of the items to include; if none
                  are provided, all values will be included
    :return: dictionary of values, keyed by field name
    :raises: :exc:`IndexError` if an out-of-bounds index is specified
    """
    # Assume the record stores field names in self._keys (list or tuple)
    # and values in self._values (list or tuple).
    if not hasattr(self, "_keys") or not hasattr(self, "_values"):
        raise AttributeError("Record object must have _keys and _values attributes")

    keys_list = list(keys)
    if not keys_list:
        # Return all fields
        return dict(zip(self._keys, self._values))

    result = {}
    for k in keys_list:
        if isinstance(k, int):
            # Index-based access
            if k < 0 or k >= len(self._values):
                raise IndexError(f"Index {k} out of bounds for record with {len(self._values)} values")
            field_name = self._keys[k]
            result[field_name] = self._values[k]
        elif isinstance(k, str):
            # Key-based access
            if k in self._keys:
                idx = self._keys.index(k)
                result[k] = self._values[idx]
            else:
                result[k] = None
        else:
            raise TypeError(f"Key {k!r} must be an int or str, not {type(k).__name__}")
    return result

def discard(self, n=-1, qid=-1, dehydration_hooks=None,
                hydration_hooks=None, **handlers):
        """
        Appends a DISCARD message to the output queue.

        :param n: number of records to discard, default = -1 (ALL)
        :param qid: query ID to discard for, default = -1 (last query)
        :param dehydration_hooks:
            Hooks to dehydrate types (dict from type (class) to dehydration
            function). Dehydration functions receive the value and returns an
            object of type understood by packstream.
        :param hydration_hooks:
            Hooks to hydrate types (mapping from type (class) to
            dehydration function). Dehydration functions receive the value of
            type understood by packstream and are free to return anything.
        :param handlers: handler functions passed into the returned Response object
        """
        # Validate input types
        if not isinstance(n, int):
            raise TypeError(f"n must be an int, got {type(n).__name__}")
        if not isinstance(qid, int):
            raise TypeError(f"qid must be an int, got {type(qid).__name__}")

        # Prepare the base message
        message = {
            "type": "DISCARD",
            "n": n,
            "qid": qid
        }

        # Apply dehydration hooks if provided
        if dehydration_hooks:
            for key, value in list(message.items()):
                hook = dehydration_hooks.get(type(value))
                if hook:
                    try:
                        message[key] = hook(value)
                    except Exception as exc:
                        raise ValueError(
                            f"Dehydration hook for {type(value).__name__} "
                            f"raised an exception: {exc}"
                        ) from exc

        # Append the message to the output queue
        try:
            # Assume self._output_queue is a queue-like object with put_nowait
            self._output_queue.put_nowait(message)
        except AttributeError:
            raise RuntimeError(
                "Output queue not initialized or does not support put_nowait"
            )
        except Exception as exc:
            raise RuntimeError(f"Failed to enqueue DISCARD message: {exc}") from exc

        # Return a Response object that will handle the result
        # The Response class is assumed to accept the message and handler functions
        return Response(message, **handlers)

def begin(self, mode=None, bookmarks=None, metadata=None, timeout=None,
              db=None, imp_user=None, dehydration_hooks=None,
              hydration_hooks=None, **handlers):
        """
        Appends a BEGIN message to the output queue.

        :param mode: access mode for routing - "READ" or "WRITE" (default)
        :param bookmarks: iterable of bookmark values after which this transaction should begin
        :param metadata: custom metadata dictionary to attach to the transaction
        :param timeout: timeout for transaction execution (seconds)
        :param db: name of the database against which to begin the transaction
            Requires Bolt 4.0+.
        :param imp_user: the user to impersonate
            Requires Bolt 4.4+
        :param dehydration_hooks:
            Hooks to dehydrate types (dict from type (class) to dehydration
            function). Dehydration functions receive the value and returns an
            object of type understood by packstream.
        :param hydration_hooks:
            Hooks to hydrate types (mapping from type (class) to
            dehydration function). Dehydration functions receive the value of
            type understood by packstream and are free to return anything.
        :param handlers: handler functions passed into the returned Response object
        :return: Response object
        """
        # Validate mode
        if mode is None:
            mode = "WRITE"
        if mode not in ("READ", "WRITE"):
            raise ValueError("mode must be 'READ' or 'WRITE'")

        # Validate bookmarks
        if bookmarks is not None:
            try:
                bookmarks = list(bookmarks)
            except TypeError:
                raise ValueError("bookmarks must be an iterable")

        # Validate metadata
        if metadata is not None and not isinstance(metadata, dict):
            raise ValueError("metadata must be a dict")

        # Validate timeout
        if timeout is not None:
            if not isinstance(timeout, (int, float)):
                raise ValueError("timeout must be a number")
            if timeout <= 0:
                raise ValueError("timeout must be positive")

        # Validate db
        if db is not None and not isinstance(db, str):
            raise ValueError("db must be a string")

        # Validate imp_user
        if imp_user is not None and not isinstance(imp_user, str):
            raise ValueError("imp_user must be a string")

        # Validate hooks
        if dehydration_hooks is not None:
            if not isinstance(dehydration_hooks, dict):
                raise ValueError("dehydration_hooks must be a dict")
            for t, fn in dehydration_hooks.items():
                if not callable(fn):
                    raise ValueError(f"dehydration hook for {t} is not callable")
        if hydration_hooks is not None:
            if not isinstance(hydration_hooks, dict):
                raise ValueError("hydration_hooks must be a dict")
            for t, fn in hydration_hooks.items():
                if not callable(fn):
                    raise ValueError(f"hydration hook for {t} is not callable")

        # Build the BEGIN message payload
        payload = {
            "mode": mode,
            "bookmarks": bookmarks or [],
            "metadata": metadata or {},
            "timeout": timeout,
            "db": db,
            "imp_user": imp_user,
            "dehydration_hooks": dehydration_hooks,
            "hydration_hooks": hydration_hooks,
        }

        # Remove None values to keep message compact
        payload = {k: v for k, v in payload.items() if v is not None}

        # Append the message to the output queue
        try:
            self._output_queue.append(("BEGIN", payload))
        except AttributeError:
            raise RuntimeError("Output queue not initialized")

        # Return a Response object that will handle the server reply
        return Response(self, handlers)

def point_type(name, fields, srid_map):
    """ Dynamically create a Point subclass. """
    # Validate the class name
    if not isinstance(name, str):
        raise TypeError(f"name must be a string, got {type(name).__name__}")

    # Validate and normalize the fields iterable
    try:
        field_list = list(fields)
    except TypeError:
        raise TypeError("fields must be an iterable of field names")

    for f in field_list:
        if not isinstance(f, str):
            raise TypeError(f"field names must be strings, got {type(f).__name__}")
        if not f.isidentifier():
            raise ValueError(f"field name '{f}' is not a valid identifier")

    # Validate the SRID mapping
    if not isinstance(srid_map, dict):
        raise TypeError(f"srid_map must be a dict, got {type(srid_map).__name__}")

    # Prepare the class dictionary
    class_dict = {"srid_map": srid_map}
    if field_list:
        class_dict["__slots__"] = field_list

    # Create the subclass of Point
    try:
        cls = type(name, (Point,), class_dict)
    except Exception as exc:
        raise RuntimeError(f"Failed to create Point subclass '{name}': {exc}") from exc

    return cls

def deprecated(message):
    """ Decorator for deprecating functions and methods.

    ::

        @deprecated("'foo' has been deprecated in favour of 'bar'")
        def foo(x):
            pass

    """
    if not isinstance(message, str):
        raise TypeError("message must be a string")
    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            warnings.warn(message, category=DeprecationWarning, stacklevel=2)
            return func(*args, **kwargs)
        return wrapper
    return decorator

