def cached(cache, key=hashkey, lock=None):
    """Decorator to wrap a function with a memoizing callable that saves
    results in a cache.

    """
    def decorator(func):
        if cache is None:
            def wrapper(*args, **kwargs):
                return func(*args, **kwargs)
        elif lock is None:
            def wrapper(*args, **kwargs):
                k = key(*args, **kwargs)
                try:
                    return cache[k]
                except KeyError:
                    pass  # key not found
                v = func(*args, **kwargs)
                try:
                    cache[k] = v
                except ValueError:
                    pass  # value too large
                return v
        else:
            def wrapper(*args, **kwargs):
                k = key(*args, **kwargs)
                try:
                    with lock:
                        return cache[k]
                except KeyError:
                    pass  # key not found
                v = func(*args, **kwargs)
                try:
                    with lock:
                        cache[k] = v
                except ValueError:
                    pass  # value too large
                return v
        return wrapper
    return decorator

def popitem(self):
    """Remove and return the `(key, value)` pair first inserted."""
    try:
        # Get the first key in insertion order
        key = next(iter(self))
    except StopIteration:
        # The container is empty
        raise KeyError('dictionary is empty')
    # Remove the key and retrieve its value
    value = self.pop(key)
    return (key, value)

def setdefault(self, key, default=None):
    """ D.setdefault(k[,d]) -> D.get(k,d), also set D[k]=d if k not in D """
    # Validate key is hashable
    try:
        hash(key)
    except TypeError:
        raise TypeError("setdefault: key must be hashable")

    # Retrieve the underlying dictionary
    storage = getattr(self, "_value", None)
    if storage is None:
        raise AttributeError("setdefault: underlying storage '_value' not found")

    # Return existing value or set default
    if key in storage:
        return storage[key]
    else:
        storage[key] = default
        return default

