def reset(self):
    """Reset the histogram.

    Current context is reset to an empty dict.
    Bins are reinitialized with the *initial_value*
    or with *make_bins()* (depending on the initialization).
    """
    try:
        # Reset context
        self.context = {}

        # Reinitialize bins
        if hasattr(self, "initial_value") and self.initial_value is not None:
            # If bins already exist, preserve their length
            if hasattr(self, "bins") and isinstance(self.bins, (list, tuple)):
                self.bins = [self.initial_value] * len(self.bins)
            else:
                # No existing bins; create an empty list
                self.bins = []
        else:
            # Fall back to make_bins if available
            make_bins = getattr(self, "make_bins", None)
            if callable(make_bins):
                result = make_bins()
                if isinstance(result, (list, tuple)):
                    self.bins = result
                else:
                    raise TypeError("make_bins() must return a list or tuple of bins")
            else:
                # No method to create bins; default to empty list
                self.bins = []

    except Exception as exc:
        raise RuntimeError(f"Failed to reset histogram: {exc}") from exc

def to_csv(self, separator=",", header=None):
    """.. deprecated:: 0.5 in Lena 0.5 to_csv is not used.
          Iterables are converted to tables.

    Convert graph's points to CSV.

    *separator* delimits values, the default is comma.

    *header*, if not ``None``, is the first string of the output
    (new line is added automatically).

    Since a graph can be multidimensional,
    for each point first its coordinate is converted to string
    (separated by *separator*), then each part of its value.

    To convert :class:`Graph` to CSV inside a Lena sequence,
    use :class:`lena.output.ToCSV`.
    """
    # Basic validation
    if not isinstance(separator, str):
        raise TypeError("separator must be a string")
    if header is not None and not isinstance(header, str):
        raise TypeError("header must be a string or None")

    try:
        points = list(self.points)
    except AttributeError:
        raise AttributeError("The object does not have a 'points' attribute")
    except Exception as exc:
        raise RuntimeError(f"Failed to access points: {exc}") from exc

    rows = []
    for idx, point in enumerate(points):
        try:
            coord, value = point
        except Exception as exc:
            raise ValueError(f"Point at index {idx} is not a (coord, value) pair") from exc

        # Convert coordinate
        if isinstance(coord, (list, tuple)):
            coord_str = separator.join(str(c) for c in coord)
        else:
            coord_str = str(coord)

        # Convert value
        if value is None:
            value_str = ""
        elif isinstance(value, (list, tuple)):
            value_str = separator.join(str(v) for v in value)
        elif isinstance(value, str):
            value_str = value
        else:
            value_str = str(value)

        rows.append(f"{coord_str}{separator}{value_str}")

    csv_output = "\n".join(rows)
    if header is not None:
        csv_output = f"{header}\n{csv_output}"
    return csv_output

def _get_err_indices(self, coord_name):
    """Get error indices corresponding to a coordinate."""
    import numpy as np
    try:
        # Retrieve the error data structure
        errors = getattr(self, 'errors', None)
        if errors is None:
            return []

        # If errors is a mapping from coordinate names to arrays
        if isinstance(errors, dict):
            if coord_name not in errors:
                return []
            err_val = errors[coord_name]
        else:
            # Assume the attribute itself is the error array for the coordinate
            err_val = errors

        if err_val is None:
            return []

        # Convert to a NumPy array if necessary
        if hasattr(err_val, 'values'):
            err_arr = np.array(err_val.values)
        else:
            err_arr = np.array(err_val)

        # Handle scalar error values
        if err_arr.ndim == 0:
            return [0] if not np.isnan(err_arr) else []

        # If the array is boolean, treat all indices as valid
        if err_arr.dtype.kind == 'b':
            return list(range(len(err_arr)))

        # Return indices where the error is not NaN
        return np.where(~np.isnan(err_arr))[0].tolist()
    except Exception:
        # In case of any unexpected error, return an empty list
        return []

