        key_regex = re.compile(r'^[a-zA-Z0-9_-]+$')
    try:
        value_regex = LABEL_VALUE_REGEX
    except NameError:
        import re
        value_regex = re.compile(r'^[a-zA-Z0-9_-]+$')

    for key, value in labels.items():
        # Validate key type
        if not isinstance(key, (str, bytes)):
            errors.append({str(key): 'expected string or bytes-like object'})
        else:
            # Decode bytes to str for regex matching
            key_str = key.decode() if isinstance(key, bytes) else key
            if not key_regex.match(key_str):
                errors.append({key_str: f"Label key '{key_str}' does not match the regex {key_regex.pattern}"})

        # Validate value type
        if isinstance(value, (list, tuple)):
            # For list/tuple values, treat the whole container as a single value
            if not isinstance(value, (str, bytes)):
                errors.append({str(value): 'expected string or bytes-like object'})
            else:
                value_str = value.decode() if isinstance(value, bytes) else value
                if not value_regex.match(value_str):
                    errors.append({value_str: f"Label value '{value_str}' does not match the regex {value_regex.pattern}"})
        else:
            if not isinstance(value, (str, bytes)):
                errors.append({str(value): 'expected string or bytes-like object'})
            else:
                value_str = value.decode() if isinstance(value, bytes) else value
                if not value_regex.match(value_str):
                    errors.append({value_str: f"Label value '{value_str}' does not match the regex {value_regex.pattern}"})

    if errors:
        raise ValidationError(errors)

def validate_value(value):
    """
    Validate the given value against the corresponding regular expression.

    Args:
        value: the string to validate

    Raises:
        ValidationError: if the given value is not conform to the regular expression.
    """
    if not isinstance(value, str):
        raise ValidationError("Value must be a string")

    # The regex pattern should be defined elsewhere, e.g., as a global variable named REGEX.
    try:
        if not hasattr(validate_value, "_compiled_regex"):
            validate_value._compiled_regex = re.compile(REGEX)
    except re.error as exc:
        raise ValidationError(f"Invalid regex pattern: {exc}") from exc

    if not validate_value._compiled_regex.match(value):
        raise ValidationError(f"Value '{value}' does not match the pattern {REGEX}")

def generate_default_observer_schema_dict(manifest_dict, first_level=False):
    """Together with :func:``generate_default_observer_schema_list``, this function is
    called recursively to generate part of a default ``observer_schema`` from part of a
    Kubernetes resource, defined respectively by ``manifest_dict`` or ``manifest_list``.

    Args:
        manifest_dict (dict): Partial Kubernetes resources
        first_level (bool, optional): If True, indicates that the dictionary represents
            the whole observer schema of a Kubernetes resource

    Returns:
        dict: Generated partial observer_schema

    This function creates a new dictionary from ``manifest_dict`` and replaces all
    non-list and non-dict values by ``None``.

    In case of ``first_level`` dictionary (i.e. complete ``observer_schema`` for a
    resource), the values of the identifying fields are copied from the manifest file.

    """
    if not isinstance(manifest_dict, dict):
        raise TypeError("manifest_dict must be a dict, got %r" % type(manifest_dict).__name__)

    def _process(value, is_first_level=False):
        if isinstance(value, dict):
            processed = {}
            for k, v in value.items():
                processed[k] = _process(v, is_first_level=False)
            if is_first_level:
                # Preserve identifying fields from the original dict
                for id_field in ("apiVersion", "kind", "metadata"):
                    if id_field in value:
                        processed[id_field] = value[id_field]
            return processed
        elif isinstance(value, list):
            return [_process(item, is_first_level=False) if isinstance(item, (dict, list)) else None
                    for item in value]
        else:
            return None

    return _process(manifest_dict, is_first_level=first_level)

def update_last_applied_manifest_list_from_resp(
    last_applied_manifest, observer_schema, response
):
    """Together with :func:`update_last_applied_manifest_dict_from_resp`, this
    function is called recursively to update a partial ``last_applied_manifest``
    from a partial Kubernetes response.

    Args:
        last_applied_manifest (list): partial ``last_applied_manifest`` being
            updated
        observer_schema (list): partial ``observer_schema``
        response (list): partial response from the Kubernetes API.

    This function goes through all observed fields, and initializes their value
    in ``last_applied_manifest`` if they are not yet present.
    """
    # Basic type checks
    if not isinstance(last_applied_manifest, dict):
        raise TypeError(
            f"last_applied_manifest must be a dict, got {type(last_applied_manifest).__name__}"
        )
    if not isinstance(observer_schema, list):
        raise TypeError(
            f"observer_schema must be a list, got {type(observer_schema).__name__}"
        )
    if not isinstance(response, dict):
        raise TypeError(
            f"response must be a dict, got {type(response).__name__}"
        )

    for field in observer_schema:
        # Nested schema represented as a dict: {key: nested_schema}
        if isinstance(field, dict):
            for key, nested_schema in field.items():
                # Ensure the key exists in the manifest
                if key not in last_applied_manifest:
                    # If the response contains the key, copy it; otherwise set to empty dict
                    last_applied_manifest[key] = response.get(key, {})
                # Recurse into nested structures
                if isinstance(nested_schema, list):
                    # Nested list schema – treat the value as a dict
                    nested_value = last_applied_manifest.get(key, {})
                    if not isinstance(nested_value, dict):
                        nested_value = {}
                        last_applied_manifest[key] = nested_value
                    update_last_applied_manifest_dict_from_resp(
                        nested_value, nested_schema, response.get(key, {})
                    )
                elif isinstance(nested_schema, dict):
                    nested_value = last_applied_manifest.get(key, {})
                    if not isinstance(nested_value, dict):
                        nested_value = {}
                        last_applied_manifest[key] = nested_value
                    update_last_applied_manifest_dict_from_resp(
                        nested_value, nested_schema, response.get(key, {})
                    )
        else:
            # Simple field name
            if field not in last_applied_manifest:
                last_applied_manifest[field] = response.get(field, None)
    # No explicit return needed – the manifest is mutated in place.

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    if app is None:
        raise ValueError("app must not be None")
    try:
        spec = getattr(app, 'spec', None)
        if spec is None:
            raise AttributeError("app has no 'spec' attribute")
        manifest = getattr(spec, 'manifest', None)
        if manifest is None:
            raise AttributeError("spec has no 'manifest' attribute")
        observer_schema = getattr(spec, 'observer_schema', None)
        if observer_schema is None:
            observer_schema = {}
            setattr(spec, 'observer_schema', observer_schema)
        # Iterate over resources in the manifest
        if isinstance(manifest, dict):
            resources = manifest.keys()
        elif isinstance(manifest, list):
            resources = [item.get('kind') for item in manifest if isinstance(item, dict) and 'kind' in item]
        else:
            resources = []
        for resource_name in resources:
            if resource_name and resource_name not in observer_schema:
                # Default schema watches metadata.name and metadata.namespace
                observer_schema[resource_name] = {
                    "metadata": {
                        "name": {"type": "string"},
                        "namespace": {"type": "string"}
                    }
                }
    except Exception as exc:
        raise RuntimeError(f"Failed to generate default observer schema: {exc}") from exc

def validate(self, path):
    """Validate OCFL object at path or pyfs root.

    Returns True if valid (warnings permitted), False otherwise.
    """
    if not path:
        return False
    try:
        # Handle pyfilesystem root objects
        if hasattr(path, "getinfo"):
            root = path
            try:
                info = root.getinfo(".ocfl_version")
                if info.is_dir:
                    return False
            except Exception:
                return False
            return True
        # Handle string or Path-like objects
        if not os.path.isdir(path):
            return False
        ocfl_version_path = os.path.join(path, ".ocfl_version")
        if not os.path.isfile(ocfl_version_path):
            return False
        try:
            with open(ocfl_version_path, "r") as f:
                version = f.read().strip()
            if not version:
                return False
        except Exception:
            return False
        return True
    except Exception:
        return False

def status_str(self, prefix=''):
    """Return string of validator status, with optional prefix."""
    status = getattr(self, 'status', None)
    if status is None:
        return prefix
    if hasattr(status, 'name'):
        status_str = status.name
    else:
        status_str = str(status)
    return f"{prefix}{status_str}"

def status_str(self, prefix=''):
    """Return string representation of validation log, with optional prefix."""
    # Ensure prefix is a string; if None, treat as empty string
    try:
        prefix = '' if prefix is None else str(prefix)
    except Exception:
        prefix = ''
    try:
        # Retrieve the log attribute; if missing, return empty string
        log_entries = getattr(self, 'log', None)
        if log_entries is None:
            return ''
        # Accept list, tuple, or any iterable of entries
        if not hasattr(log_entries, '__iter__'):
            raise TypeError("log attribute must be iterable")
        lines = []
        for entry in log_entries:
            try:
                # Convert each entry to string; if fails, use placeholder
                entry_str = str(entry)
            except Exception:
                entry_str = '<unrepresentable entry>'
            lines.append(f"{prefix}{entry_str}")
        return "\n".join(lines)
    except Exception as exc:
        # In case of unexpected errors, return a descriptive message
        return f"{prefix}<error generating status: {exc}>"

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    # Basic input validation
    if not isinstance(inventory, dict):
        raise TypeError("inventory must be a dict")
    if version is not None and not isinstance(version, str):
        raise TypeError("version must be a string or None")

    # Helper to compare versions
    def _ge(v1, v2):
        """Return True if v1 >= v2."""
        try:
            from packaging.version import parse as _parse
            return _parse(v1) >= _parse(v2)
        except Exception:
            # Fallback: compare numeric parts of the version string
            def _split(v):
                parts = []
                for part in v.split('.'):
                    num = ''
                    for ch in part:
                        if ch.isdigit():
                            num += ch
                        else:
                            break
                    parts.append(int(num) if num else 0)
                return parts
            return _split(v1) >= _split(v2)

    result = {}
    for logical_path, data in inventory.items():
        content_files = set()
        # Handle dict mapping version -> content_file
        if isinstance(data, dict):
            for ver, content in data.items():
                if version is None or _ge(ver, version):
                    content_files.add(content)
        # Handle list of (version, content_file) tuples
        elif isinstance(data, list):
            for item in data:
                if isinstance(item, (list, tuple)) and len(item) == 2:
                    ver, content = item
                    if version is None or _ge(ver, version):
                        content_files.add(content)
        # If data is a single content file string, include it
        elif isinstance(data, str):
            content_files.add(data)
        # Skip unsupported formats
        if content_files:
            result[logical_path] = content_files
    return result

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    if fixity is None:
        raise ValueError("Fixity block is missing")
    if not isinstance(fixity, dict):
        raise ValueError("Fixity block must be a dictionary")

    if 'files' not in fixity:
        raise ValueError("Fixity block must contain a 'files' key")
    files = fixity['files']
    if not isinstance(files, list):
        raise ValueError("'files' entry must be a list")

    if manifest_files is None:
        raise ValueError("Manifest files list is missing")
    manifest_set = set(manifest_files)

    required_keys = {'path', 'hash', 'size'}
    for idx, entry in enumerate(files):
        if not isinstance(entry, dict):
            raise ValueError(f"File entry at index {idx} must be a dictionary")
        missing = required_keys - entry.keys()
        if missing:
            raise ValueError(f"File entry at index {idx} missing keys: {', '.join(missing)}")
        path = entry['path']
        if not isinstance(path, str):
            raise ValueError(f"File entry at index {idx} has non-string path")
        if path not in manifest_set:
            raise ValueError(f"File entry at index {idx} references unknown path '{path}'")
    return True

def files_list(path):
    """
    Return the files in `path`
    """
    if not os.path.exists(path):
        raise FileNotFoundError(path)
    if os.path.isfile(path):
        return [os.path.abspath(path)]
    if os.path.isdir(path):
        try:
            return [os.path.abspath(os.path.join(path, f))
                    for f in os.listdir(path)
                    if os.path.isfile(os.path.join(path, f))]
        except OSError as exc:
            raise exc
    raise ValueError(f"Unsupported path type: {path}")

def _explore_folder(folder):
    """
    Get packages' data from folder

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    folder : str
        Folder of the package
    Returns
    -------
    dict
    """
    import os
    data = {}
    try:
        if not os.path.isdir(folder):
            raise ValueError(f"Provided path '{folder}' is not a directory")
        # First find all XML files to identify package basenames
        xml_basenames = set()
        for entry in os.listdir(folder):
            full_path = os.path.join(folder, entry)
            if os.path.isfile(full_path):
                name, ext = os.path.splitext(entry)
                if ext.lower() == ".xml":
                    xml_basenames.add(name)
        # Group all files that share a basename with an XML file
        for entry in os.listdir(folder):
            full_path = os.path.join(folder, entry)
            if os.path.isfile(full_path):
                name, _ = os.path.splitext(entry)
                if name in xml_basenames:
                    data.setdefault(name, []).append(full_path)
    except Exception as exc:
        # Log or re-raise as needed; here we simply return an empty dict
        return {}
    return data

def fix_namespace_prefix_w(content):
    """Convert os textos cujo padrão é `w:st="` em `w-st="`"""
    if not isinstance(content, str):
        raise TypeError("content must be a string")
    try:
        return content.replace('w:st="', 'w-st="')
    except Exception as e:
        raise RuntimeError("Error processing content") from e

def match_pubdate(node, pubdate_xpaths):
    """
    Retorna o primeiro match da lista de pubdate_xpaths
    """
    if node is None or not pubdate_xpaths:
        return None
    for xpath in pubdate_xpaths:
        try:
            matches = node.xpath(xpath)
            if matches:
                return matches[0]
        except Exception:
            continue
    return None

def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    """
    # Validate indent argument
    if not isinstance(indent, int):
        raise TypeError("indent must be an integer")
    if indent < 0:
        indent = 0
    try:
        import pprint
        if debug:
            header = f"{type(self).__name__} (id={id(self)})\n"
            body = pprint.pformat(self, indent=indent, width=80, depth=None)
            return header + body
        else:
            return pprint.pformat(self, indent=indent, width=80, depth=None)
    except Exception:
        try:
            return str(self)
        except Exception:
            return f"<unrepresentable object {type(self).__name__}>"

def tzname_in_python2(namefunc):
    """Change unicode output into bytestrings in Python 2

    tzname() API changed in Python 3. It used to return bytes, but was changed
    to unicode strings
    """
    if not callable(namefunc):
        raise TypeError('namefunc must be a callable')
    def inner_func(*args, **kwargs):
        try:
            result = namefunc(*args, **kwargs)
        except Exception as exc:
            raise
        if PY3:
            return result
        else:
            try:
                if isinstance(result, type(u'')):
                    return result.encode()
            except Exception:
                pass
            return result
    return inner_func

def get_versions():
    """Get version information or return default if unable to do so."""
    default = "unknown"
    try:
        # Attempt to read a VERSION file in the current directory
        with open("VERSION", "r", encoding="utf-8") as f:
            version = f.read().strip()
            if version:
                return version
    except Exception:
        # Any error (file not found, permission, etc.) falls through to default
        pass
    return default

def render(pieces, style):
    """Render the given version pieces into the requested style."""
    # Validate the pieces argument
    if pieces is None:
        raise ValueError("pieces cannot be None")
    try:
        iterator = iter(pieces)
    except TypeError:
        raise TypeError("pieces must be an iterable")

    # Validate the style argument
    if not isinstance(style, str):
        raise TypeError("style must be a string")

    # Normalise style for comparison
    style_key = style.strip().lower()

    # Helper to safely convert a piece to string
    def _to_str(item):
        try:
            return str(item)
        except Exception as exc:
            raise RuntimeError(f"Unable to convert piece {item!r} to string: {exc}") from exc

    # Render according to the requested style
    try:
        if style_key == "plain":
            return "".join(_to_str(p) for p in pieces)
        elif style_key == "html":
            return "".join(f"<span>{_to_str(p)}</span>" for p in pieces)
        elif style_key == "markdown":
            return "".join(f"`{_to_str(p)}`" for p in pieces)
        else:
            raise ValueError(f"Unsupported style: {style!r}")
    except Exception as exc:
        # Wrap any unexpected error with context
        raise RuntimeError(f"Error rendering pieces with style {style!r}: {exc}") from exc

def plus_or_dot(pieces):
    """Return a + if we don't already have one, else return a ."""
    try:
        if '+' not in pieces:
            return '+'
        else:
            return '.'
    except Exception:
        # If pieces is not iterable or None, default to '+'
        return '+'

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    # Normalize inputs
    if isinstance(commands, str):
        commands = [commands]
    if args is None:
        args = []
    outputs = []
    for cmd in commands:
        # Build the command list
        if isinstance(cmd, str):
            cmd_list = shlex.split(cmd)
        else:
            cmd_list = list(cmd)
        cmd_list.extend(args)
        if verbose:
            print("Running command:", ' '.join(cmd_list))
        try:
            stderr = subprocess.DEVNULL if hide_stderr else None
            result = subprocess.run(
                cmd_list,
                cwd=cwd,
                env=env,
                stdout=subprocess.PIPE,
                stderr=stderr,
                text=True,
                check=True
            )
            outputs.append(result.stdout)
        except subprocess.CalledProcessError as e:
            raise RuntimeError(
                f"Command '{' '.join(cmd_list)}' failed with exit code {e.returncode}"
            ) from e
        except Exception as e:
            raise RuntimeError(
                f"Failed to run command '{' '.join(cmd_list)}': {e}"
            ) from e
    return outputs

def register_vcs_handler(vcs, method):  # decorator
    """Create decorator to mark a method as the handler of a VCS."""
    if not isinstance(vcs, str):
        raise TypeError("vcs must be a string")
    if not isinstance(method, str):
        raise TypeError("method must be a string")

    def decorate(f):
        """Store f in HANDLERS[vcs][method]."""
        if not callable(f):
            raise TypeError("decorated object must be callable")
        global HANDLERS
        if 'HANDLERS' not in globals():
            HANDLERS = {}
        if vcs not in HANDLERS:
            HANDLERS[vcs] = {}
        HANDLERS[vcs][method] = f
        return f

    return decorate

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    # Validate argument types
    for name, val in (('validate_objects', validate_objects),
                      ('check_digests', check_digests),
                      ('show_warnings', show_warnings)):
        if not isinstance(val, bool):
            raise TypeError(f'{name} must be a bool, got {type(val).__name__}')

    num_objects = 0
    good_objects = 0

    # Retrieve all objects in the hierarchy.  The method is expected to be
    # provided by the concrete implementation; if it is missing we raise
    # a clear error.
    try:
        objects = self._get_all_objects()
    except AttributeError:
        raise RuntimeError('Hierarchy object does not provide a _get_all_objects() method')

    # If the returned value is not iterable, treat it as an empty collection.
    if objects is None:
        objects = []

    for obj in objects:
        num_objects += 1
        is_valid = True

        # Validate the object itself if requested.
        if validate_objects:
            try:
                if hasattr(obj, 'validate'):
                    obj.validate()
                else:
                    # If no validate method, assume the object is valid.
                    pass
            except Exception as exc:
                is_valid = False
                if show_warnings:
                    print(f'Warning: object {obj!r} failed validation: {exc}')

        # Check the object's digest if requested and it hasn't already failed.
        if check_digests and is_valid:
            try:
                if hasattr(obj, 'check_digest'):
                    if not obj.check_digest():
                        is_valid = False
                        if show_warnings:
                            print(f'Warning: object {obj!r} failed digest check')
                else:
                    # If no digest check method, skip this step.
                    pass
            except Exception as exc:
                is_valid = False
                if show_warnings:
                    print(f'Warning: object {obj!r} digest check raised exception: {exc}')

        if is_valid:
            good_objects += 1

    return num_objects, good_objects

def initialize(self):
    """Create and initialize a new OCFL storage root."""
    import os
    import json
    from datetime import datetime

    root = getattr(self, "root_path", None)
    if not root:
        raise ValueError("root_path attribute is not set")

    if os.path.exists(root):
        raise FileExistsError(f"OCFL root already exists at {root}")

    try:
        os.makedirs(root, exist_ok=False)
    except OSError as exc:
        raise RuntimeError(f"Failed to create root directory {root}: {exc}") from exc

    ocfl_root_file = os.path.join(root, ".ocfl_root")
    ocfl_metadata = {
        "ocfl_version": "1.0",
        "ocfl_root": root,
        "created_at": datetime.utcnow().isoformat() + "Z",
    }
    try:
        with open(ocfl_root_file, "w", encoding="utf-8") as f:
            json.dump(ocfl_metadata, f, indent=2)
    except OSError as exc:
        raise RuntimeError(f"Failed to write .ocfl_root file: {exc}") from exc

    objects_dir = os.path.join(root, "objects")
    try:
        os.makedirs(objects_dir, exist_ok=False)
    except OSError as exc:
        raise RuntimeError(f"Failed to create objects directory: {exc}") from exc

    return True

def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    if not isinstance(version, str):
        raise TypeError("version must be a string")
    version = version.strip()
    if not version:
        return "1"
    if not version.isdigit():
        raise ValueError("version must contain only digits")
    width = len(version)
    try:
        num = int(version)
    except ValueError:
        raise ValueError("invalid numeric version")
    next_num = num + 1
    next_width = max(width, len(str(next_num)))
    return str(next_num).zfill(next_width)

def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    if not isinstance(version_dirs, (list, tuple)):
        raise TypeError("version_dirs must be a list or tuple of directory names")
    # Prepare structures
    prev_inventory = {}
    differences = {}
    root_inventory = getattr(self, "root_inventory", {})
    for idx, dir_name in enumerate(version_dirs, start=1):
        # Assume inventory file is named 'inventory.txt' inside each version dir
        inv_path = os.path.join(dir_name, "inventory.txt")
        try:
            with open(inv_path, "r", encoding="utf-8") as f:
                lines = f.readlines()
        except FileNotFoundError:
            raise ValueError(f"Missing inventory file in version directory '{dir_name}'")
        inventory = {}
