def _dictsum(dicts):
    """
    Combine values of the dictionaries supplied by iterable dicts.

    >>> _dictsum([{'a': 1, 'b': 2}, {'a': 5, 'b': 0}])
    {'a': 6, 'b': 2}
    """
    if dicts is None:
        return {}
    try:
        iterator = iter(dicts)
    except TypeError:
        raise TypeError("Expected an iterable of dictionaries")
    result = {}
    for d in iterator:
        if not isinstance(d, dict):
            raise TypeError("All items in the iterable must be dictionaries")
        for key, value in d.items():
            if key in result:
                # Only sum numeric values; otherwise replace with the new value
                if isinstance(result[key], (int, float)) and isinstance(value, (int, float)):
                    result[key] += value
                else:
                    result[key] = value
            else:
                result[key] = value
    return result

def is_none_string(val: any) -> bool:
    """Check if a string represents a None value."""
    # Direct None check
    if val is None:
        return True
    # Only strings can represent a None value in this context
    if not isinstance(val, str):
        return False
    # Strip whitespace for accurate comparison
    stripped = val.strip()
    if not stripped:
        return True
    # Common textual representations of None
    return stripped.lower() in ("none", "null", "undefined")

