def string_to_int(string: str, alphabet: List[str]) -> int:
    """
    Convert a string to a number, using the given alphabet.

    The input is assumed to have the most significant digit first.
    """
    # Validate the string argument
    if not isinstance(string, str):
        raise TypeError(f"string must be a str, got {type(string).__name__}")
    if string == "":
        raise ValueError("string must not be empty")

    # Validate the alphabet argument
    if not isinstance(alphabet, (list, tuple, str)):
        raise TypeError(f"alphabet must be a list, tuple, or str, got {type(alphabet).__name__}")

    # Normalise alphabet to a list of single‑character strings
    if isinstance(alphabet, str):
        alphabet_list = list(alphabet)
    else:
        alphabet_list = list(alphabet)

    if len(alphabet_list) == 0:
        raise ValueError("alphabet must contain at least one character")

    # Ensure all alphabet entries are single‑character strings
    for idx, ch in enumerate(alphabet_list):
        if not isinstance(ch, str) or len(ch) != 1:
            raise ValueError(f"alphabet element at position {idx} is not a single character string")

    # Ensure the alphabet contains unique characters
    if len(set(alphabet_list)) != len(alphabet_list):
        raise ValueError("alphabet must contain unique characters")

    base = len(alphabet_list)
    if base <= 1:
        raise ValueError("alphabet must contain at least two unique characters")

    # Build a mapping from character to its numeric value
    char_to_value = {ch: i for i, ch in enumerate(alphabet_list)}

    # Convert the string to an integer
    value = 0
    for pos, ch in enumerate(string):
        if ch not in char_to_value:
            raise ValueError(f"character '{ch}' at position {pos} not found in alphabet")
        value = value * base + char_to_value[ch]

    return value

def get_repo_archive(url: str, destination_path: Path) -> Path:
    """
    Given an url and a destination path, retrieve and extract .tar.gz archive
    which contains 'desc' file for each package.
    Each .tar.gz archive corresponds to an Arch Linux repo ('core', 'extra', 'community').

    Args:
        url: url of the .tar.gz archive to download
        destination_path: the path on disk where to extract archive

    Returns:
        a directory Path where the archive has been extracted to.
    """
    # Validate inputs
    if not isinstance(url, str) or not url:
        raise ValueError("url must be a non-empty string")
    if not isinstance(destination_path, Path):
        raise TypeError("destination_path must be a pathlib.Path instance")

    # Ensure destination directory exists and is empty
    try:
        destination_path.mkdir(parents=True, exist_ok=True)
    except Exception as exc:
        raise OSError(f"Could not create destination directory {destination_path}") from exc

    if any(destination_path.iterdir()):
        raise OSError(f"Destination path {destination_path} is not empty")

    # Download the archive
    try:
        resp = requests.get(url, stream=True, timeout=30)
        resp.raise_for_status()
    except Exception as exc:
        raise RuntimeError(f"Failed to download archive from {url}") from exc

    # Write to a temporary file
    import tempfile
    try:
        with tempfile.NamedTemporaryFile(delete=False, suffix=".tar.gz") as tmp_file:
            for chunk in resp.iter_content(chunk_size=8192):
                if chunk:
                    tmp_file.write(chunk)
            tmp_path = Path(tmp_file.name)
    except Exception as exc:
        raise RuntimeError("Failed to write temporary file for archive") from exc

    # Extract the archive
    try:
        import tarfile
        with tarfile.open(tmp_path, "r:gz") as tar:
            tar.extractall(path=destination_path)
    except Exception as exc:
        raise RuntimeError(f"Failed to extract archive to {destination_path}") from exc
    finally:
        # Clean up the temporary file
        try:
            tmp_path.unlink()
        except Exception:
            pass

    return destination_path

def os_is_mac():
    """
    Checks if the os is macOS

    :return: True is macOS
    :rtype: bool
    """
    try:
        # os.uname() is available on Unix-like systems including macOS
        return os.uname().sysname == 'Darwin'
    except AttributeError:
        # Fallback for systems where os.uname() is not available
        try:
            import platform
            return platform.system() == 'Darwin'
        except Exception:
            return False
    except Exception:
        return False

def unquote(name):
    """Remove quote from the given name."""
    if not isinstance(name, str):
        raise TypeError(f"Expected a string, got {type(name).__name__}")
    # Strip leading and trailing single or double quotes
    match = re.match(r"^(['\"])(.*)\1$", name)
    if match:
        return match.group(2)
    return name

