def get_pattern(pattern, strip=True):
    """
    This method converts the given string to a regex pattern.
    If the input is already a compiled regex object, it is returned unchanged.
    If the input is a string, it is optionally stripped of leading/trailing
    whitespace and then compiled.  Unsupported types raise a TypeError.
    """
    # None is treated as no pattern
    if pattern is None:
        return None

    # If it's already a compiled regex, return it
    # In Python 3.7+ re.Pattern is available; otherwise use the type of a compiled pattern
    try:
        pattern_type = re.Pattern
    except AttributeError:
        pattern_type = type(re.compile(''))
    if isinstance(pattern, pattern_type):
        return pattern

    # If it's a string, strip and compile
    if isinstance(pattern, str):
        if strip:
            pattern = pattern.strip()
        return re.compile(pattern)

    # If it looks like a compiled regex (has pattern and flags attributes), return it
    if hasattr(pattern, 'pattern') and hasattr(pattern, 'flags'):
        return pattern

    # Anything else is invalid
    raise TypeError(f"Invalid pattern type: {type(pattern).__name__}")

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    if not commands:
        raise ValueError("No command specified")
    # Build the command list
    if isinstance(commands, str):
        cmd = [commands]
    else:
        cmd = list(commands)
    if args:
        if isinstance(args, str):
            cmd.append(args)
        else:
            cmd.extend(args)
    if verbose:
        print("Running command:", " ".join(cmd))
    # Determine stderr handling
    stderr = subprocess.DEVNULL if hide_stderr else None
    try:
        result = subprocess.run(
            cmd,
            cwd=cwd,
            env=env,
            capture_output=True,
            text=True,
            stderr=stderr
        )
        result.check_returncode()
        return result
    except subprocess.CalledProcessError as e:
        raise RuntimeError(f"Command '{' '.join(cmd)}' failed with exit code {e.returncode}") from e

