def make_array(shape, dtype=np.dtype("float32")):
    """
    Function to create an array with shape and dtype.

    Parameters
    ----------
    shape : tuple
        shape of the array to create
    dtype : `numpy.dtype`
        data-type of the array to create
    """
    # Validate shape
    try:
        shape = tuple(shape)
    except Exception as exc:
        raise TypeError("shape must be a tuple of integers") from exc
    if not all(isinstance(s, int) and s >= 0 for s in shape):
        raise ValueError("shape must contain non-negative integers")

    # Validate dtype
    if not isinstance(dtype, np.dtype):
        try:
            dtype = np.dtype(dtype)
        except Exception as exc:
            raise TypeError("dtype must be a valid numpy dtype") from exc

    # Create and return the array
    return np.empty(shape, dtype)

def gaussian(x):
    """
    Gaussian centered around 0.2 with a sigma of 0.1.
    """
    mean = 0.2
    sigma = 0.1
    try:
        arr = np.asarray(x, dtype=float)
    except Exception as e:
        raise ValueError("Input x must be array-like or convertible to float.") from e
    coeff = 1.0 / (sigma * np.sqrt(2 * np.pi))
    exponent = -0.5 * ((arr - mean) / sigma) ** 2
    return coeff * np.exp(exponent)

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    """
    Given a sequence of configuration filenames, load and validate each configuration file.
    Return the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    """
    configs = {}
    errors = []

    def _expand_env(value):
        if isinstance(value, str):
            return os.path.expandvars(value)
        elif isinstance(value, dict):
            return {k: _expand_env(v) for k, v in value.items()}
        elif isinstance(value, list):
            return [_expand_env(v) for v in value]
        else:
            return value

    for fname in config_filenames:
        try:
            with open(fname, 'r') as f:
                raw = f.read()
            if fname.endswith('.toml'):
                cfg = toml.loads(raw)
            elif fname.endswith(('.yaml', '.yml')):
                cfg = yaml.safe_load(raw)
            elif fname.endswith('.json'):
                cfg = json.loads(raw)
            else:
                raise ValueError(f"Unsupported config file type: {fname}")

            if overrides:
                cfg.update(overrides)

            if resolve_env:
                cfg = _expand_env(cfg)

            configs[fname] = cfg
        except Exception as e:
            record = logging.LogRecord(
                name='config_loader',
                level=logging.ERROR,
                pathname=fname,
                lineno=0,
                msg=str(e),
                args=(),
                exc_info=None
            )
            errors.append(record)

    return configs, errors

