@classmethod
def protocol_handlers(cls, protocol_version=None):
    """ Return a dictionary of available Bolt protocol handlers,
    keyed by version tuple. If an explicit protocol version is
    provided, the dictionary will contain either zero or one items,
    depending on whether that version is supported. If no protocol
    version is provided, all available versions will be returned.

    :param protocol_version: tuple identifying a specific protocol
        version (e.g. (3, 5)) or None
    :return: dictionary of version tuple to handler class for all
        relevant and supported protocol versions
    :raise TypeError: if protocol version is not passed in a tuple
    """
    if protocol_version is not None and not isinstance(protocol_version, tuple):
        raise TypeError("protocol_version must be a tuple or None")

    # Retrieve the mapping of supported protocol handlers.
    # Subclasses may override this attribute.
    handlers = getattr(cls, "_protocol_handlers", {})

    if protocol_version is None:
        # Return a copy to prevent accidental modification of the class attribute.
        return dict(handlers)

    # Return a single-item dict if the requested version is supported,
    # otherwise return an empty dict.
    if protocol_version in handlers:
        return {protocol_version: handlers[protocol_version]}
    return {}

def from_raw_values(cls, values):
    """Create a Bookmarks object from a list of raw bookmark string values.

    You should not need to use this method unless you want to deserialize
    bookmarks.

    :param values: ASCII string values (raw bookmarks)
    :type values: Iterable[str]
    """
    # Validate that values is iterable
    try:
        iterator = iter(values)
    except TypeError:
        raise TypeError("values must be an iterable of strings")

    bookmarks = []
    for raw in iterator:
        if not isinstance(raw, str):
            raise ValueError(f"Bookmark value must be a string, got {type(raw).__name__}")
        try:
            # Assume Bookmark has a from_raw_value classmethod
            bookmark = Bookmark.from_raw_value(raw)
        except Exception as exc:
            raise ValueError(f"Failed to parse bookmark value '{raw}': {exc}") from exc
        bookmarks.append(bookmark)

    return cls(bookmarks=bookmarks)

def pop(self, key, default=__marker):
    """D.pop(k[,d]) -> v, remove specified key and return the corresponding value.
    If key is not found, d is returned if given, otherwise KeyError is raised."""
    if key not in self:
        if default is __marker:
            raise KeyError(key)
        return default
    value = self[key]
    del self[key]
    return value

def popitem(self):
    """Remove and return the `(key, value)` pair least frequently used."""
    try:
        # Ensure the cache has items
        if not hasattr(self, "_freq") or not self._freq:
            raise KeyError("cache is empty")

        # Find the minimum frequency
        min_freq = min(self._freq.values())

        # Retrieve the bucket that holds keys with this frequency
        freq_buckets = getattr(self, "_freq_buckets", {})
        bucket = freq_buckets.get(min_freq)
        if bucket is None:
            raise KeyError("no items with the minimum frequency")

        # Pop the first key-value pair (FIFO order within the bucket)
        key, value = bucket.popitem(last=False)

        # Clean up the key from the frequency map
        del self._freq[key]

        # If the bucket is now empty, remove it and adjust the min frequency
        if not bucket:
            del freq_buckets[min_freq]
            # Optionally update a cached min frequency attribute if present
            if hasattr(self, "_minfreq"):
                self._minfreq = min(freq_buckets) if freq_buckets else None

        return (key, value)
    except KeyError:
        # Re-raise KeyError to signal an empty cache or missing key
        raise
    except Exception as exc:
        # Wrap any other unexpected errors in a KeyError for consistency
        raise KeyError(f"unexpected error during popitem: {exc}")

def popitem(self):
    """Remove and return the `(key, value)` pair most recently used."""
    try:
        # Attempt to pop the most recently used item from the underlying
        # ordered mapping.  The attribute name may vary; try common names.
        if hasattr(self, "_cache"):
            return self._cache.popitem(last=True)
        if hasattr(self, "_data"):
            return self._data.popitem(last=True)
        if hasattr(self, "data"):
            return self.data.popitem(last=True)
        # If none of the expected attributes exist, raise an informative error.
        raise AttributeError("No suitable ordered mapping attribute found")
    except KeyError:
        # The underlying mapping is empty.
        raise KeyError("dict is empty")

