def identify_request(request: RequestType) -> bool:
    """
    Try to identify whether this is a Matrix request
    """
    try:
        if request is None:
            return False

        # Check the request path – Matrix API endpoints usually start with /_matrix/
        path = getattr(request, "path", None)
        if isinstance(path, str) and path.startswith("/_matrix/"):
            return True

        # Fallback to inspecting HTTP headers / content type
        meta = getattr(request, "META", {})
        if isinstance(meta, dict):
            content_type = meta.get("CONTENT_TYPE", "")
            if "application/json" in content_type:
                # Some Matrix clients set a custom header to indicate a Matrix request
                if meta.get("HTTP_X_MATRIX_REQUEST") is not None:
                    return True

        return False
    except Exception:
        # In case of any unexpected error, conservatively return False
        return False

def format_dt(dt):
    """Format a datetime in the way that D* nodes expect."""
    if not isinstance(dt, datetime):
        raise TypeError("dt must be a datetime instance")
    # Ensure the datetime is timezone-aware and in UTC
    if dt.tzinfo is None:
        dt = dt.replace(tzinfo=datetime.timezone.utc)
    else:
        dt = dt.astimezone(datetime.timezone.utc)
    # Return ISO 8601 string with trailing 'Z' to indicate UTC
    return dt.strftime("%Y-%m-%dT%H:%M:%SZ")

def process_text_links(text):
    """Process links in text, adding some attributes and linkifying textual links."""
    if not isinstance(text, str):
        raise TypeError("text must be a string")
    try:
        # Regex to find http/https URLs
        url_pattern = r'(https?://[^\s]+)'
        def _replace(match):
            url = match.group(0)
            # Add target and rel attributes for security and usability
            return f'<a href="{url}" target="_blank" rel="noopener noreferrer">{url}</a>'
        return re.sub(url_pattern, _replace, text)
    except Exception:
        # In case of any regex or runtime error, return the original text unchanged
        return text

def test_tag(tag: str) -> bool:
    """Test a word whether it could be accepted as a tag."""
    try:
        if not isinstance(tag, str):
            raise TypeError("'tag' must be a string")
        tag = tag.strip()
        if not tag:
            return False
        # Tag must be 1-30 characters, only letters, digits, hyphens, or underscores
        if len(tag) > 30:
            return False
        import re
        pattern = re.compile(r'^[A-Za-z0-9_-]+$')
        return bool(pattern.match(tag))
    except Exception:
        return False

def xml_children_as_dict(node):
    """Turn the children of node <xml> into a dict, keyed by tag name.

    This is only a shallow conversation - child nodes are not recursively processed.
    """
    result = {}
    try:
        for child in node:
            tag = child.tag
            if tag in result:
                existing = result[tag]
                if isinstance(existing, list):
                    existing.append(child)
                else:
                    result[tag] = [existing, child]
            else:
                result[tag] = child
    except Exception as exc:
        raise TypeError(f"Expected an ElementTree element, got {type(node).__name__}") from exc
    return result

def get_nodeinfo_well_known_document(url, document_path=None):
    """Generate a NodeInfo .well-known document.

    See spec: http://nodeinfo.diaspora.software

    :arg url: The full base url with protocol, ie https://example.com
    :arg document_path: Custom NodeInfo document path if supplied (optional)
    :returns: dict
    """
    # Validate the base URL
    if not isinstance(url, str) or not url:
        raise ValueError("url must be a non-empty string")
    base_url = url.rstrip("/")
    # Determine the document path
    if document_path is None:
        doc_path = "/.well-known/nodeinfo"
    else:
        if not isinstance(document_path, str):
            raise ValueError("document_path must be a string")
        # Ensure leading slash
        if not document_path.startswith("/"):
            doc_path = "/" + document_path
        else:
            doc_path = document_path
        # Remove trailing slash
        doc_path = doc_path.rstrip("/")
    # Construct the NodeInfo document URL
    nodeinfo_url = f"{base_url}{doc_path}/1.0"
    # Build the .well-known document
    return {
        "links": [
            {
                "rel": "http://nodeinfo.diaspora.software/ns/schema/1.0",
                "href": nodeinfo_url
            }
        ]
    }

def verify_relayable_signature(public_key, doc, signature):
    """
    Verify the signed XML elements to have confidence that the claimed
    author did actually generate this message.
    """
    try:
        import os
        from lxml import etree
        import xmlsec
    except Exception:
        # Required libraries are not available
        return False

    if not public_key or not doc or not signature:
        return False

    try:
        # Parse the XML document
        if isinstance(doc, str):
            root = etree.fromstring(doc.encode('utf-8'))
        else:
            root = doc

        # Find the Signature element
        sig_node = root.find('.//{http://www.w3.org/2000/09/xmldsig#}Signature')
        if sig_node is None:
            return False

        # Optionally compare the provided signature value
        sig_value_node = sig_node.find('.//{http://www.w3.org/2000/09/xmldsig#}SignatureValue')
        if sig_value_node is not None:
            if sig_value_node.text.strip() != signature.strip():
                return False

        # Prepare the verification context
        ctx = xmlsec.SignatureContext()

        # Load the public key (file path or PEM string)
        if os.path.exists(public_key):
            key = xmlsec.Key.from_file(public_key, xmlsec.KeyFormat.PEM)
        else:
            key = xmlsec.Key.from_memory(public_key.encode('utf-8'), xmlsec.KeyFormat.PEM)

        ctx.key = key

        # Perform the verification
        ctx.verify(sig_node)
        return True
    except Exception:
        # Any error during parsing or verification results in False
        return False

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    if not isinstance(document, str) or not document.strip():
        return None

    # Try JSON first
    try:
        data = json.loads(document)
        subject = data.get("subject")
        aliases = data.get("aliases", [])
        links = data.get("links", [])
        # Ensure links is a list of dicts
        parsed_links = []
        for link in links:
            if isinstance(link, dict):
                parsed_links.append(link)
        return {"subject": subject, "aliases": aliases, "links": parsed_links}
    except Exception:
        # Fall back to XRD (XML) parsing
        try:
            root = ET.fromstring(document)
            ns = {"xrd": "http://docs.oasis-open.org/ns/xri/xrd-1.0"}
            subject_elem = root.find("xrd:Subject", ns)
            subject = subject_elem.text if subject_elem is not None else None
            aliases = [a.text for a in root.findall("xrd:Alias", ns) if a.text]
            links = []
            for link_elem in root.findall("xrd:Link", ns):
                rel = link_elem.attrib.get("rel")
                type_ = link_elem.attrib.get("type")
                href = link_elem.attrib.get("href")
                template = link_elem.attrib.get("template")
                link_dict = {"rel": rel, "type": type_, "href": href}
                if template:
                    link_dict["template"] = template
                links.append(link_dict)
            return {"subject": subject, "aliases": aliases, "links": links}
        except Exception:
            return None

def retrieve_and_parse_diaspora_webfinger(handle):
    """
    Retrieve a and parse a remote Diaspora webfinger document.

    :arg handle: Remote handle to retrieve
    :returns: dict
    """
    try:
        host = handle.split("@")[1]
    except (AttributeError, IndexError):
        logger.warning("retrieve_and_parse_diaspora_webfinger: invalid handle given: %s", handle)
        return None
    document, code, exception = fetch_document(
        host=host, path="/.well-known/webfinger?resource=acct:%s" % quote(handle),
    )
    if document:
        return parse_diaspora_webfinger(document)
    hostmeta = retrieve_diaspora_host_meta(host)
    if not hostmeta:
        return None
    url = hostmeta.find_link(rels="lrdd").template.replace("{uri}", quote(handle))
    document, code, exception = fetch_document(url)
    if exception:
        return None
    return parse_diaspora_webfinger(document)

def retrieve_diaspora_host_meta(host):
    """
    Retrieve a remote Diaspora host-meta document.

    :arg host: Host to retrieve from
    :returns: ``XRD`` instance
    """
    if not host:
        logger.warning("retrieve_diaspora_host_meta: invalid host provided: %s", host)
        return None
    try:
        document, code, exception = fetch_document(host=host, path="/.well-known/host-meta")
    except Exception as exc:
        logger.exception("retrieve_diaspora_host_meta: error fetching host-meta for host %s: %s", host, exc)
        return None
    if exception or not document:
        return None
    try:
        xrd = XRD.parse_xrd(document)
    except Exception as exc:
        logger.exception("retrieve_diaspora_host_meta: error parsing XRD for host %s: %s", host, exc)
        return None
    return xrd

def list_of_file_names(settings_dirs, spec_option):
    """Create a new IniType complex type
    """
    try:
        dirs = settings_dirs if isinstance(settings_dirs, (list, tuple)) else [settings_dirs]
        files = []
        for d in dirs:
            if not os.path.isdir(d):
                continue
            for fname in os.listdir(d):
                if fname.endswith(spec_option):
                    files.append(os.path.join(d, fname))
        return sorted(files)
    except Exception:
        return []

