@classmethod
def validate_from_content(cls, spec_content=None):
    """validates that spec (YAML) content has all required fields

    :param spec_content: content of spec file
    :raise IRValidatorException: when mandatory data
    is missing in spec file
    :return: Dictionary with data loaded from a spec (YAML) file
    """
    if spec_content is None:
        raise IRValidatorException("spec_content must be provided")
    try:
        data = yaml.safe_load(spec_content)
    except Exception as e:
        raise IRValidatorException(f"Error parsing YAML content: {e}")
    if data is None or not isinstance(data, dict):
        raise IRValidatorException("Spec content must be a YAML mapping")
    # Determine required fields: use class attribute if defined, otherwise default list
    required_fields = getattr(cls, "REQUIRED_FIELDS", ["name", "type", "spec_version"])
    missing = [field for field in required_fields if field not in data]
    if missing:
        raise IRValidatorException(f"Missing required fields: {', '.join(missing)}")
    return data

@classmethod
    def validate_from_file(cls, yaml_file=None):
        """Loads & validates that a YAML file has all required fields

        :param yaml_file: Path to YAML file
        :raise IRValidatorException: when mandatory data is missing in file
        :return: Dictionary with data loaded from a YAML file
        """
        if yaml_file is None:
            raise IRValidatorException("yaml_file argument must be supplied")

        try:
            with open(yaml_file, "r") as f:
                data = yaml.safe_load(f)
        except FileNotFoundError as e:
            raise IRValidatorException(f"File not found: {yaml_file}") from e
        except yaml.YAMLError as e:
            raise IRValidatorException(f"Error parsing YAML file: {e}") from e

        if not isinstance(data, dict):
            raise IRValidatorException("YAML file does not contain a mapping at the top level")

        required_fields = getattr(cls, "REQUIRED_FIELDS", [])
        missing = [field for field in required_fields if field not in data]
        if missing:
            raise IRValidatorException(f"Missing mandatory fields: {', '.join(missing)}")

        return data

def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files."""
    if not isinstance(parser_dict, dict):
        raise TypeError('parser_dict must be a dict')
    # Helper to merge two dicts recursively
    def _merge(target, source):
        for key, value in source.items():
            if key == 'include':
                continue
            if key in target and isinstance(target[key], dict) and isinstance(value, dict):
                _merge(target[key], value)
            else:
                target[key] = value
    # Resolve includes
    for name, spec in list(parser_dict.items()):
        if not isinstance(spec, dict):
            continue
        includes = spec.pop('include', None)
        if not includes:
            continue
        if not isinstance(includes, (list, tuple)):
            raise TypeError(f'include value for {name} must be a list or tuple')
        for inc_name in includes:
            inc_spec = parser_dict.get(inc_name)
            if inc_spec is None:
                raise KeyError(f'Included parser "{inc_name}" not found for "{name}"')
            if not isinstance(inc_spec, dict):
                raise TypeError(f'Included parser "{inc_name}" must be a dict')
            _merge(spec, inc_spec)
    # After merging, remove any remaining include keys
    for spec in parser_dict.values():
        spec.pop('include', None)

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources. """
    defaults = {}
    for arg in self.args:
        if not isinstance(arg, _BaseOpt):
            continue

        # Resolve value from spec if available, otherwise use the option's default
        if getattr(self, "spec", None) and arg.name in self.spec:
            value = self.spec[arg.name]
        else:
            value = arg.default

        if not isinstance(value, NoDefault):
            defaults[arg.name] = value

        # If the option is a dictionary option with its own scheme,
        # recursively resolve defaults for that nested scheme.
        if isinstance(arg, DictOption) and getattr(arg, "scheme", None):
            nested = arg.scheme.get_spec_defaults()
            if nested:
                defaults[arg.name] = nested

    return defaults

def get_deprecated_args(self):
    """Returning dict with options which deprecate others."""
    return {
        # Deprecated argument name: new argument name
        # Example mappings – replace with actual deprecated options
        'old_option': 'new_option',
        'legacy_mode': 'mode',
    }

def get_parser_option_specs(self, command_name):
    """Gets all the options for the specified command

    :param command_name: the command name (main, virsh, ospd, etc...)
    :return: the list of all command options
    """
    if not isinstance(command_name, str):
        raise TypeError("command_name must be a string")

    # The command options are expected to be stored in a dictionary.
    # Try the most common attribute names.
    options_dict = getattr(self, "_command_options", None)
    if options_dict is None:
        options_dict = getattr(self, "command_options", {})

    if not isinstance(options_dict, dict):
        raise TypeError("Command options should be a dictionary")

    # Return the options for the requested command, or an empty list if not found.
    return options_dict.get(command_name, [])

def get_option_spec(self, command_name, argument_name):
    """Gets the specification for the specified option name. """
    # Validate input types
    if not isinstance(command_name, str) or not command_name:
        raise ValueError("command_name must be a non-empty string")
    if not isinstance(argument_name, str) or not argument_name:
        raise ValueError("argument_name must be a non-empty string")

    try:
        # Retrieve the command object
        cmd = self.commands[command_name]
    except KeyError:
        raise ValueError(f"Command '{command_name}' not found") from None
    except AttributeError:
        raise RuntimeError("The object does not have a 'commands' attribute") from None

    try:
        # Retrieve the option specification
        spec = cmd.options[argument_name]
    except KeyError:
        raise ValueError(f"Option '{argument_name}' not found in command '{command_name}'") from None
    except AttributeError:
        raise RuntimeError(f"Command '{command_name}' does not have an 'options' attribute") from None

    return spec

def get_silent_args(self, args):
    """list of silenced argument

    :param args: The received arguments.
    :return: list, slienced argument names
    """
    try:
        if not isinstance(args, (list, tuple)):
            return []
        silent_args = [arg for arg in args
                       if isinstance(arg, str) and arg.startswith('-') and arg != '--']
        return silent_args
    except Exception:
        return []

def validate_requires_args(self, args):
    """Check if all the required arguments have been provided. """
    # Ensure args is a mapping of argument names to values
    if not isinstance(args, dict):
        raise TypeError("args must be a dict of argument names to values")

    # Retrieve the list/tuple of required argument names
    required = getattr(self, "required_args", None)
    if required is None:
        raise AttributeError("The instance does not define a 'required_args' attribute")

    # Ensure required is iterable
    try:
        iter(required)
    except TypeError:
        raise TypeError("'required_args' must be an iterable of argument names")

    # Find any missing required arguments
    missing = [name for name in required if name not in args or args[name] is None]

    if missing:
        raise ValueError(f"Missing required argument(s): {', '.join(missing)}")

def _get_conditionally_required_args(self, command_name, options_spec, args):
    """List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when``
        condition
    """
    required = []
    for opt in options_spec:
        # Retrieve option name
        if isinstance(opt, dict):
            name = opt.get('name')
            cond = opt.get('required_when')
        else:
            name = getattr(opt, 'name', None)
            cond = getattr(opt, 'required_when', None)

        if not name or cond is None:
            continue

        # If condition is a mapping of command names, pick the one for this command
        if isinstance(cond, dict):
            cond = cond.get(command_name)
            if cond is None:
                continue

        try:
            if callable(cond):
                match = cond(args)
            elif isinstance(cond, str):
                # Evaluate the string expression with args available
                match = eval(cond, {}, {'args': args})
            else:
                match = bool(cond)
        except Exception as exc:
            raise ValueError(
                f"Error evaluating required_when for option '{name}': {exc}"
            ) from exc

        if match:
            required.append(name)

    return required

def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    """
    if not isinstance(args, dict):
        raise TypeError(f"args must be a dict (got {type(args).__name__})")

    # Retrieve argument specifications from parsed YAML
    arg_specs = self.parsed_yaml.get('args', {})
    if not isinstance(arg_specs, dict):
        raise TypeError(f"parsed_yaml['args'] must be a dict (got {type(arg_specs).__name__})")

    for arg_name, value in args.items():
        # Skip if no specification for this argument
        spec = arg_specs.get(arg_name)
        if not isinstance(spec, dict):
            continue

        max_len = spec.get('length')
        if max_len is None:
            continue

        # Validate max_len type and value
        if not isinstance(max_len, int):
            raise TypeError(
                f"Length constraint for argument '{arg_name}' must be an integer (got {type(max_len).__name__})"
            )
        if max_len < 0:
            raise ValueError(
                f"Length constraint for argument '{arg_name}' must be non-negative (got {max_len})"
            )

        # Skip None values
        if value is None:
            continue

        # Ensure the value has a length
        try:
            val_len = len(value)
        except TypeError:
            raise TypeError(
                f"Argument '{arg_name}' does not support len() (value type: {type(value).__name__})"
            )

        if val_len > max_len:
            raise ValueError(
                f"Argument '{arg_name}' length {val_len} exceeds maximum allowed {max_len}"
            )

def validate_choices_args(self, args):
    """Check if value of choice arguments is one of the available choices.

    :param args: The received arguments.
    """
    # Retrieve argument definitions from the parsed YAML configuration
    arg_defs = getattr(self, "parsed_yaml", {}).get("args", {})
    if not isinstance(arg_defs, (dict, list)):
        # If the structure is unexpected, skip validation
        return

    # Helper to validate a single argument against its choices
    def _validate(arg_name, arg_attrs, value):
        choices = arg_attrs.get("choices")
        if choices is None:
            return
        if value not in choices:
            raise ValueError(
                f"Invalid value for argument '{arg_name}': {value!r}. "
                f"Expected one of {choices}."
            )

    # Handle dictionary-based argument definitions
    if isinstance(arg_defs, dict):
        for arg_name, arg_attrs in arg_defs.items():
            if arg_name in args:
                _validate(arg_name, arg_attrs, args[arg_name])

    # Handle list-based argument definitions (list of single-key dicts)
    else:
        for arg_dict in arg_defs:
            if isinstance(arg_dict, dict):
                for arg_name, arg_attrs in arg_dict.items():
                    if arg_name in args:
                        _validate(arg_name, arg_attrs, args[arg_name])

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    # Ensure the instance has min_ and max_ attributes
    if not hasattr(self, 'min_') or not hasattr(self, 'max_'):
        raise AttributeError("Instance must have 'min_' and 'max_' attributes")
    min_val = self.min_
    max_val = self.max_
    if min_val is None or max_val is None:
        raise ValueError("min_ and max_ must not be None")
    if min_val > max_val:
        raise ValueError("min_ must be less than or equal to max_")

    # Determine the iterable of values to validate
    if isinstance(args, dict):
        values = args.values()
    else:
        try:
            values = iter(args)
        except TypeError:
            raise TypeError("args must be an iterable or a dict")

    # Validate each value
    for idx, val in enumerate(values):
        if val is None:
            raise TypeError(f"Argument at position {idx} is None")
        try:
            if val < min_val or val > max_val:
                raise ValueError(
                    f"Argument at position {idx} with value {val} is out of bounds [{min_val}, {max_val}]"
                )
        except TypeError:
            raise TypeError(
                f"Argument at position {idx} with value {val!r} is not comparable to min/max"
            )
    return args

def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra-vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    """
    if vars_dict is None:
        raise ValueError("vars_dict must be a dictionary")
    if not isinstance(vars_dict, dict):
        raise TypeError("vars_dict must be a dict")
    if extra_vars is None:
        return vars_dict
    if isinstance(extra_vars, dict):
        vars_dict.update(extra_vars)
        return vars_dict
    if not isinstance(extra_vars, (list, tuple)):
        raise TypeError("extra_vars must be a list or dict")
    for item in extra_vars:
        if isinstance(item, dict):
            vars_dict.update(item)
        elif isinstance(item, (list, tuple)) and len(item) == 2:
            key, value = item
            vars_dict[key] = value
        else:
            raise ValueError(f"Invalid extra_vars item: {item}")
    return vars_dict

def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None,
                     extra_vars=None, ansible_args=None):
    """Wraps the 'ansible-playbook' CLI.

     :param ir_workspace: An Infrared Workspace object represents the active
     :param ir_plugin: An InfraredPlugin object of the current plugin
     :param playbook_path: the playbook to invoke
     :param verbose: Ansible verbosity level
     :param extra_vars: dict. Passed to Ansible as extra-vars
     :param ansible_args: dict of ansible-playbook arguments to plumb down
         directly to Ansible.
    """
    # Build the base command
    command = ["ansible-playbook"]

    # Handle verbosity
    if verbose is not None:
        if isinstance(verbose, int):
            command.append("-" + "v" * verbose)
        else:
            command.append(str(verbose))

    # Add extra variables if provided
    if extra_vars:
        try:
            import json
            command.extend(["--extra-vars", json.dumps(extra_vars)])
        except Exception as exc:
            raise RuntimeError(f"Failed to serialize extra_vars: {exc}") from exc

    # Add any additional ansible-playbook arguments
    if ansible_args:
        for key, value in ansible_args.items():
            if isinstance(value, bool):
                if value:
                    command.append(f"--{key}")
            else:
                command.append(f"--{key}={value}")

    # Append the playbook path
    command.append(playbook_path)

    # Execute the command
    try:
        import subprocess
        result = subprocess.run(
            command,
            capture_output=True,
            text=True,
            check=False
        )
    except Exception as exc:
        raise RuntimeError(f"Failed to execute ansible-playbook: {exc}") from exc

    # Raise an error if Ansible reported a failure
    if result.returncode != 0:
        raise RuntimeError(
            f"Ansible returned non-zero exit status {result.returncode}: {result.stderr}"
        )

    # Return the captured stdout
    return result.stdout

def _convert_non_cli_args(self, parser_name, values_dict):
    """
    Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    # Define simple type conversion helpers
    def _to_bool(val):
        truthy = {"true", "1", "yes", "y"}
        falsy = {"false", "0", "no", "n"}
        if val.lower() in truthy:
            return True
        if val.lower() in falsy:
            return False
        raise ValueError

    # Iterate over a copy of items to avoid runtime changes during iteration
    for key, val in list(values_dict.items()):
        # Skip non-string values or None
        if val is None or not isinstance(val, str):
            continue

        s = val.strip()
        if s == "":
            continue

        # Attempt boolean conversion first
        try:
            values_dict[key] = _to_bool(s)
            continue
        except ValueError:
            pass

        # Attempt integer conversion
        try:
            values_dict[key] = int(s)
            continue
        except ValueError:
            pass

        # Attempt float conversion
        try:
            values_dict[key] = float(s)
            continue
        except ValueError:
            pass

        # Attempt comma‑separated list conversion
        if "," in s:
            values_dict[key] = [item.strip() for item in s.split(",")]
            continue

        # If none of the above, keep the original string
    return values_dict

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    import json

    # Validate input
    if not isinstance(plugin_dir, str) or not os.path.isdir(plugin_dir):
        return {}

    # Determine the spec file (default to plugin.json)
    spec_file = os.path.join(plugin_dir, 'plugin.json')
    if not os.path.isfile(spec_file):
        return {}

    try:
        with open(spec_file, 'r', encoding='utf-8') as f:
            spec_data = json.load(f)
    except Exception:
        # If the file cannot be read or parsed, return an empty dict
        return {}

    def _flatten(d, parent_key=''):
        """Recursively flatten a nested dictionary."""
        items = {}
        for key, value in d.items():
            new_key = f"{parent_key}.{key}" if parent_key else key
            if isinstance(value, dict):
                items.update(_flatten(value, new_key))
            else:
                items[new_key] = value
        return items

    return _flatten(spec_data)

def inject_config(self):
    """Set the environment variable for config path, if it is undefined."""
    import os
    env_var = 'CONFIG_PATH'
    # Only set if the environment variable is not already defined
    if os.getenv(env_var) is None:
        # Ensure the instance has a config_path attribute
        if not hasattr(self, 'config_path'):
            raise AttributeError("Instance has no 'config_path' attribute")
        # Validate the config_path value
        config_path = self.config_path
        if config_path is None:
            raise ValueError("config_path is None; cannot set environment variable")
        # Convert to string if it's a Path-like object
        try:
            config_path_str = str(config_path)
        except Exception as exc:
            raise ValueError(f"config_path cannot be converted to string: {exc}") from exc
        os.environ[env_var] = config_path_str
    # No return value needed; the environment variable is set in place.

def extend_cli(self, root_subparsers):
    """
    Adds the spec cli options to the main entry point.

    :param subparser: the subparser object to extend.
    """
    if root_subparsers is None:
        raise ValueError("root_subparsers cannot be None")
    try:
        spec_parser = root_subparsers.add_parser('spec', help='Spec command')
        spec_parser.add_argument('spec', help='Spec to resolve')
        spec_parser.add_argument('-o', '--output', help='Output file', default=None)
    except AttributeError as e:
        raise TypeError("root_subparsers must support add_parser") from e
    except Exception as e:
        raise RuntimeError(f"Error adding spec CLI options: {e}") from e

def strip_root(path, root):
    """Remove root from path, throw exception on failure."""
    if not isinstance(path, str) or not isinstance(root, str):
        raise TypeError("path and root must be strings")
    if root == "":
        raise ValueError("root cannot be an empty string")
    norm_path = os.path.abspath(os.path.normpath(path))
    norm_root = os.path.abspath(os.path.normpath(root))
    try:
        rel = os.path.relpath(norm_path, norm_root)
    except ValueError as exc:
        # On Windows, ValueError is raised if paths are on different drives
        raise ValueError(f"Cannot strip root: {exc}") from exc
    if rel == ".":
        return ""
    if rel.startswith(".."):
        raise ValueError(f"Path '{path}' is not under root '{root}'")
    return rel
